(998014, 119575, 21905, '<td valign="top">Cute.  I like your concept.</td>', 'Cute.  I like your concept.', '2004-11-08 00:16:06.000000', NULL, 1),
(998018, 118778, 6870, '<td valign="top">This looks familiar . . . I love the colors and also the composition. It works for me! 8</td>', 'This looks familiar . . . I love the colors and also the composition. It works for me! 8', '2004-11-08 00:16:39.000000', NULL, 1),
(998031, 119018, 13365, '<td valign="top">nice shot, border is a bit excessive and distracting</td>', 'nice shot, border is a bit excessive and distracting', '2004-11-08 00:19:31.000000', NULL, 1),
(998047, 119576, 29134, '<td valign="top">Marvelous image John</td>', 'Marvelous image John', '2004-11-08 00:23:18.000000', NULL, 1),
(998055, 119336, 18194, '<td valign="top">wow great photo..10</td>', 'wow great photo..10', '2004-11-08 00:26:18.000000', NULL, 1),
(998057, 119179, 6804, '<td valign="top">WOW!    My first 10.... This is beautiful!<br/>The color looks natural and not over saturated. Great depth of field from the foreground leaves back to the last trees. Very nice color combo with the rich green against the red leaves.</td>', 'WOW!    My first 10.... This is beautiful!The color looks natural and not over saturated. Great depth of field from the foreground leaves back to the last trees. Very nice color combo with the rich green against the red leaves.', '2004-11-08 00:26:54.000000', NULL, 1),
(998065, 119453, 20539, '<td valign="top">great expression</td>', 'great expression', '2004-11-08 00:29:27.000000', NULL, 1),
(998068, 118781, 20539, '<td valign="top">u got water on your lens =)</td>', 'u got water on your lens =)', '2004-11-08 00:30:03.000000', NULL, 1),
(998075, 119435, 15811, '<td valign="top">Beautiful photo.  While it fits the challenge and all that I''m sure, I must just be missing what makes the photo April besides the title.  I''m taking your word for it though.  Nice shot!</td>', 'Beautiful photo.  While it fits the challenge and all that I''m sure, I must just be missing what makes the photo April besides the title.  I''m taking your word for it though.  Nice shot!', '2004-11-08 00:32:31.000000', NULL, 1),
(998082, 118335, 15811, '<td valign="top">A bit too much sky for my taste.  Possible you could have cropped out a good bit of that sky and maybe utilized the rule of thirds.  Looks great though when I scroll down some :-)  great shot!</td>', 'A bit too much sky for my taste.  Possible you could have cropped out a good bit of that sky and maybe utilized the rule of thirds.  Looks great though when I scroll down some :-)  great shot!', '2004-11-08 00:34:51.000000', NULL, 1),
(998093, 118607, 15811, '<td valign="top">It''s a great shot and meets the challenge well...My only constructive critisism would be that there seems to be a bit too much beach for my taste.  Otherwise, great shot.</td>', 'It''s a great shot and meets the challenge well...My only constructive critisism would be that there seems to be a bit too much beach for my taste.  Otherwise, great shot.', '2004-11-08 00:36:38.000000', NULL, 1),
(998094, 119572, 7969, '<td valign="top">how i wish i were here....nice shot, one of the better ones so far.</td>', 'how i wish i were here....nice shot, one of the better ones so far.', '2004-11-08 00:37:22.000000', NULL, 1),
(998105, 117915, 4805, '<td valign="top">That cat looks happy to be doing that.</td>', 'That cat looks happy to be doing that.', '2004-11-08 00:43:00.000000', NULL, 1),
(998107, 119453, 4805, '<td valign="top">Great photo of your dog (I mean that - it''s awesome) but a bit of a stretch challenge-wise.</td>', 'Great photo of your dog (I mean that - it''s awesome) but a bit of a stretch challenge-wise.', '2004-11-08 00:44:01.000000', NULL, 1),
(998110, 118387, 10432, '<td valign="top">The photo looks lovely.  Great color and sharpness.  The frame seems to dwarf the photo - and is unfortunately distracting - it draws my eyes away from the photol.</td>', 'The photo looks lovely.  Great color and sharpness.  The frame seems to dwarf the photo - and is unfortunately distracting - it draws my eyes away from the photol.', '2004-11-08 00:44:43.000000', NULL, 1),
(998111, 119576, 20539, '<td valign="top">well thats a first as far as i know on this site. kudos on braveness, and good luck with the stuck up crowd. i bet youll get a few giggles from the negative comments...</td>', 'well thats a first as far as i know on this site. kudos on braveness, and good luck with the stuck up crowd. i bet youll get a few giggles from the negative comments...', '2004-11-08 00:44:48.000000', NULL, 1),
