(998127, 119582, 10170, '<td valign="top">Professional model and lighting?  Certainly good enough to be on both counts,  Great stuff. 10</td>', 'Professional model and lighting?  Certainly good enough to be on both counts,  Great stuff. 10', '2004-11-08 00:51:20.000000', NULL, 1),
(998129, 119183, 10432, '<td valign="top">Great colors and cute pup.  But the face is OOF.  Composition isn''t quite right - not enough negative space maybe.</td>', 'Great colors and cute pup.  But the face is OOF.  Composition isn''t quite right - not enough negative space maybe.', '2004-11-08 00:52:11.000000', NULL, 1),
(998132, 118939, 10170, '<td valign="top">Cute/saucy model, love her smile.  Great lighting.  Heaps of fun.  Absolutely love it.  10</td>', 'Cute/saucy model, love her smile.  Great lighting.  Heaps of fun.  Absolutely love it.  10', '2004-11-08 00:53:11.000000', NULL, 1),
(998138, 119581, 15511, '<td valign="top">Great idea!</td>', 'Great idea!', '2004-11-08 00:56:36.000000', NULL, 1),
(998164, 119336, 10432, '<td valign="top">Beautiful capture - great timing!  I love how the white dog pops out from the colored leaves. The one leaf right above the the dogs face/ear is just a bit distracting.  Nicely done, though and good luck!</td>', 'Beautiful capture - great timing!  I love how the white dog pops out from the colored leaves. The one leaf right above the the dogs face/ear is just a bit distracting.  Nicely done, though and good luck!', '2004-11-08 01:01:33.000000', NULL, 1),
