(1000868, 119304, 14603, '<td valign="top">Simple but effective..definitely calendar material.</td>', 'Simple but effective..definitely calendar material.', '2004-11-09 11:42:50.000000', NULL, 1),
(1000912, 118859, 19035, '<td valign="top">Call a doctor!  The waffles have been shot!!  just kidding, very original.  7</td>', 'Call a doctor!  The waffles have been shot!!  just kidding, very original.  7', '2004-11-09 12:15:10.000000', NULL, 1),
(1000914, 117915, 19035, '<td valign="top">He doen''t seem to enjoy this very much...but as long as it makes you happy, just kidding, funny photo. 6</td>', 'He doen''t seem to enjoy this very much...but as long as it makes you happy, just kidding, funny photo. 6', '2004-11-09 12:16:49.000000', NULL, 1),
(1000940, 118974, 27986, '<td valign="top">Actually, i think it''s great! How did you manage to separate the leaves from the other colors, like the background?</td>', 'Actually, i think it''s great! How did you manage to separate the leaves from the other colors, like the background?', '2004-11-09 12:35:04.000000', NULL, 1),
(1000941, 119453, 27986, '<td valign="top">Cute critter</td>', 'Cute critter', '2004-11-09 12:36:45.000000', NULL, 1),
(1000943, 118944, 9073, '<td valign="top">Although the clouds are lovely, their lack of definition would annoy me if I had to look at them for a whole month. 4<br/></td>', 'Although the clouds are lovely, their lack of definition would annoy me if I had to look at them for a whole month. 4', '2004-11-09 12:38:42.000000', NULL, 1),
(1000946, 119330, 9073, '<td valign="top">Fantastic idea, well executed. 9</td>', 'Fantastic idea, well executed. 9', '2004-11-09 12:39:20.000000', NULL, 1),
(1000948, 119336, 9073, '<td valign="top">Beautiful. Closer cropping would bring out the eye line from the dog to the leaf. 9</td>', 'Beautiful. Closer cropping would bring out the eye line from the dog to the leaf. 9', '2004-11-09 12:40:05.000000', NULL, 1),
(1000950, 118939, 27986, '<td valign="top">Succesful shot!</td>', 'Succesful shot!', '2004-11-09 12:41:08.000000', NULL, 1),
(1000952, 119437, 27986, '<td valign="top">Is that real Northern lights, or have you enhanced it some? Great anyway!</td>', 'Is that real Northern lights, or have you enhanced it some? Great anyway!', '2004-11-09 12:42:05.000000', NULL, 1),
(1000953, 119374, 9073, '<td valign="top">"Yes" was my first thought on seeing this. A great image. The edges are a bit dark indicating that your polarising filter use was too close to your focal limit, but this is digital, so ... I don''t know. 9</td>', '"Yes" was my first thought on seeing this. A great image. The edges are a bit dark indicating that your polarising filter use was too close to your focal limit, but this is digital, so ... I don''t know. 9', '2004-11-09 12:42:22.000000', NULL, 1),
(1000956, 119338, 27986, '<td valign="top">Hehe, nice!</td>', 'Hehe, nice!', '2004-11-09 12:42:39.000000', NULL, 1),
(1000958, 119525, 9073, '<td valign="top">A nice image, but somewhat meandering. 5</td>', 'A nice image, but somewhat meandering. 5', '2004-11-09 12:43:10.000000', NULL, 1),
(1000961, 119026, 9073, '<td valign="top">This would make a nice calendar photo. Effective and clear. Maybe the top is too boring, though. 7</td>', 'This would make a nice calendar photo. Effective and clear. Maybe the top is too boring, though. 7', '2004-11-09 12:43:53.000000', NULL, 1),
(1000964, 118341, 9073, '<td valign="top">Nice idea. For this to work effectively, you could think about brightening the image and using selective blur to mystify the effect a bit. 5</td>', 'Nice idea. For this to work effectively, you could think about brightening the image and using selective blur to mystify the effect a bit. 5', '2004-11-09 12:45:34.000000', NULL, 1),
(1000966, 118731, 9073, '<td valign="top">For a calendar, the branches at the top would annoy me on repeated viewing. 5</td>', 'For a calendar, the branches at the top would annoy me on repeated viewing. 5', '2004-11-09 12:46:23.000000', NULL, 1),
