(1000972, 119399, 9073, '<td valign="top">The rocks at the bottom are blue tinged. But I love the sky. 7</td>', 'The rocks at the bottom are blue tinged. But I love the sky. 7', '2004-11-09 12:47:55.000000', NULL, 1),
