(1001403, 119569, 13602, '<td valign="top">Why the tiled horizon?</td>', 'Why the tiled horizon?', '2004-11-09 16:32:14.000000', NULL, 1),
(1001409, 118479, 13602, '<td valign="top">Just a bit better focus wouldn''t hurt here.</td>', 'Just a bit better focus wouldn''t hurt here.', '2004-11-09 16:35:18.000000', NULL, 1),
(1001410, 119534, 6999, '<td valign="top">I don''t find anything here that particularly says ''November'' to me - for either Hemisphere - mainly, i think, the complete absence of any seasonal plants hurts you. It could, quite honestly, be almost any time of year in my eyes. <br/> <br/>Neither does it have the punchm that quality of light, of drama in the landscape that I''d want in a calendar shot. <br/> <br/>I do quite like the compositional idea - but i think it cries out for stronger colours, perhaps a half stop or so less exposure, which has the effect of intensifying colour: here there is that slightly pale feeling so typical of a camera''s automatic exposure setting. 5</td>', 'I don''t find anything here that particularly says ''November'' to me - for either Hemisphere - mainly, i think, the complete absence of any seasonal plants hurts you. It could, quite honestly, be almost any time of year in my eyes.  Neither does it have the punchm that quality of light, of drama in the landscape that I''d want in a calendar shot.  I do quite like the compositional idea - but i think it cries out for stronger colours, perhaps a half stop or so less exposure, which has the effect of intensifying colour: here there is that slightly pale feeling so typical of a camera''s automatic exposure setting. 5', '2004-11-09 16:36:29.000000', NULL, 1),
(1001413, 119576, 13602, '<td valign="top">Beautiful... I like the softness and feeling here, I can''t really connect it to february but who cares? I''ll pretend it''s a Playboy calendar or something like that...</td>', 'Beautiful... I like the softness and feeling here, I can''t really connect it to february but who cares? I''ll pretend it''s a Playboy calendar or something like that...', '2004-11-09 16:37:47.000000', NULL, 1),
(1001415, 119155, 6999, '<td valign="top">Excellent work here - wonderful control of exposure. I wonder if, perhaps, it isn''t slightly too suggestive of a house fire for the normally required blandness of calendar photography - something along the lines of a family silhouetted by it would add that inoffensiveness that seems normal. But nevertheless, and wonderfully executed photograph. Love that structure of burning pallets. 8</td>', 'Excellent work here - wonderful control of exposure. I wonder if, perhaps, it isn''t slightly too suggestive of a house fire for the normally required blandness of calendar photography - something along the lines of a family silhouetted by it would add that inoffensiveness that seems normal. But nevertheless, and wonderfully executed photograph. Love that structure of burning pallets. 8', '2004-11-09 16:39:39.000000', NULL, 1),
(1001419, 118778, 6999, '<td valign="top">I do like that suggested continuity of the clouds through the building. As a calendar shot? Apart from having little to place it in any particular time of year, it feels just a touch too unorthodox to my eye. Don''t misunderstand - I like the idea, and the execution but for a couple of reservations about graduation of light - I''m just not sure about it as a calendar shot.</td>', 'I do like that suggested continuity of the clouds through the building. As a calendar shot? Apart from having little to place it in any particular time of year, it feels just a touch too unorthodox to my eye. Don''t misunderstand - I like the idea, and the execution but for a couple of reservations about graduation of light - I''m just not sure about it as a calendar shot.', '2004-11-09 16:43:21.000000', NULL, 1),
(1001421, 119181, 6999, '<td valign="top">Nice portrait, and especially given the trickiness of the white shirt and black top abd keeping some texture on both. Can''t really see it as a claendar shot, myself, but good work.</td>', 'Nice portrait, and especially given the trickiness of the white shirt and black top abd keeping some texture on both. Can''t really see it as a claendar shot, myself, but good work.', '2004-11-09 16:45:05.000000', NULL, 1),
(1001422, 119553, 6999, '<td valign="top">Strange light here. I like the idea, and think it would work just fine, but your concentration of light feels a bit bizarre, and the angle of it, or perhaps simply the processing or size of image, has allowed  no real sense of depth or texture to come through. A shame, as it would be an ideally themed shot for a calendar.</td>', 'Strange light here. I like the idea, and think it would work just fine, but your concentration of light feels a bit bizarre, and the angle of it, or perhaps simply the processing or size of image, has allowed  no real sense of depth or texture to come through. A shame, as it would be an ideally themed shot for a calendar.', '2004-11-09 16:47:06.000000', NULL, 1),
(1001426, 118525, 6999, '<td valign="top">Clever - quite what it is that speaks of autumn here, rather than simply a black and white shot of a leaf at any time is difficult to say. I suppose the border woudl be acceptable for a calendar, though it still behoves me to say how little I like it. I''ve enjoyed the shot though, for all those criticisms.</td>', 'Clever - quite what it is that speaks of autumn here, rather than simply a black and white shot of a leaf at any time is difficult to say. I suppose the border woudl be acceptable for a calendar, though it still behoves me to say how little I like it. I''ve enjoyed the shot though, for all those criticisms.', '2004-11-09 16:49:13.000000', NULL, 1),
(1001431, 118370, 13602, '<td valign="top">Beautiful image, I would buy this calendar, just a little comment, I see a small color problem the hole image has a bit too much green and looks like lacking blue. But it''s really in small amount. Especially in her skin there is too much green visible.</td>', 'Beautiful image, I would buy this calendar, just a little comment, I see a small color problem the hole image has a bit too much green and looks like lacking blue. But it''s really in small amount. Especially in her skin there is too much green visible.', '2004-11-09 16:51:25.000000', NULL, 1),
(1001434, 119577, 6999, '<td valign="top">Wonderfully well done, and glad to see you''ve avoided the current disease of over-enhancing the light and shade in such scenes. Either great fortune or great patience eviddent, and great understanding of light, and I''m also pleased about your balance of shadow and light. Good graphic sense of composition also, coupled with a great depth of detail in the image, for all the slight digital noise in the sky. I''m not sure it''s quite what i would choose out of a stock catalogue for a calendar shot - doesn''t have the right cliched quality, really, but that''s largely incidental. 7</td>', 'Wonderfully well done, and glad to see you''ve avoided the current disease of over-enhancing the light and shade in such scenes. Either great fortune or great patience eviddent, and great understanding of light, and I''m also pleased about your balance of shadow and light. Good graphic sense of composition also, coupled with a great depth of detail in the image, for all the slight digital noise in the sky. I''m not sure it''s quite what i would choose out of a stock catalogue for a calendar shot - doesn''t have the right cliched quality, really, but that''s largely incidental. 7', '2004-11-09 16:53:11.000000', NULL, 1),
(1001437, 119221, 6999, '<td valign="top">:-) Or any other month, come to that, huh? neat shot, neat idea of graphic qualities to it. I feel i''ve been here, but can''t recall where it is?</td>', ':-) Or any other month, come to that, huh? neat shot, neat idea of graphic qualities to it. I feel i''ve been here, but can''t recall where it is?', '2004-11-09 16:54:31.000000', NULL, 1),
(1001443, 119435, 6999, '<td valign="top">I''m guessing this is some kind of ludicrous theme-park sort of thing, or Vegas, or somewhere weirdly crass like that. I''ve never seen it before, however, and so it has a certain impact. So strange. doesn''t speak of any time of year particularly, to me, but I could imagine it in a calendar. just not a claendar I;d particularly want to have hanging on my wall :-) Good work. 7</td>', 'I''m guessing this is some kind of ludicrous theme-park sort of thing, or Vegas, or somewhere weirdly crass like that. I''ve never seen it before, however, and so it has a certain impact. So strange. doesn''t speak of any time of year particularly, to me, but I could imagine it in a calendar. just not a claendar I;d particularly want to have hanging on my wall :-) Good work. 7', '2004-11-09 16:57:00.000000', NULL, 1),
(1001505, 118472, 3102, '<td valign="top">Yeesh... was there a nuclear explosion nearby?  I''m really not fond of what happened to the sky here... :(</td>', 'Yeesh... was there a nuclear explosion nearby?  I''m really not fond of what happened to the sky here... :(', '2004-11-09 18:11:52.000000', NULL, 1),
(1001531, 119564, 20779, '<td valign="top">Can''t say much except "perfect".</td>', 'Can''t say much except "perfect".', '2004-11-09 18:33:01.000000', NULL, 1),
(1001532, 119190, 20779, '<td valign="top">Love the "eye" that caught and composed this. Terrific lighting. One of my favorites.</td>', 'Love the "eye" that caught and composed this. Terrific lighting. One of my favorites.', '2004-11-09 18:33:36.000000', NULL, 1),
(1001536, 119061, 20779, '<td valign="top">My first 10 in this challenge so far. Fascinating shot and processing.</td>', 'My first 10 in this challenge so far. Fascinating shot and processing.', '2004-11-09 18:34:30.000000', NULL, 1),
(1001537, 119374, 20779, '<td valign="top">Pristine and beautiful expanse. Perfect ''calendar" shot.</td>', 'Pristine and beautiful expanse. Perfect ''calendar" shot.', '2004-11-09 18:34:55.000000', NULL, 1),
(1001538, 119336, 20779, '<td valign="top">The little crook in his right leg is great. Adds to the overall dynamic feeling. I will buy the calendar when it comes out!</td>', 'The little crook in his right leg is great. Adds to the overall dynamic feeling. I will buy the calendar when it comes out!', '2004-11-09 18:35:57.000000', NULL, 1),
(1001540, 119524, 20779, '<td valign="top">This has a magical feel to me. I love the light poking through, although some may say the opposite. I just noticed the little blue patch this time through - but it won''t change my score.  Very unique composition.</td>', 'This has a magical feel to me. I love the light poking through, although some may say the opposite. I just noticed the little blue patch this time through - but it won''t change my score.  Very unique composition.', '2004-11-09 18:37:37.000000', NULL, 1),
(1001541, 119399, 20779, '<td valign="top">The colors, the rocks floating in the front, the dynamic lines - all add up to a wow and a 10.</td>', 'The colors, the rocks floating in the front, the dynamic lines - all add up to a wow and a 10.', '2004-11-09 18:38:25.000000', NULL, 1),
(1001543, 118479, 20779, '<td valign="top">Just precious. I think I would have liked to see the handle left desaturated, but no big deal. Just fabulous mood and look captured. Great composition within the frame. 9.</td>', 'Just precious. I think I would have liked to see the handle left desaturated, but no big deal. Just fabulous mood and look captured. Great composition within the frame. 9.', '2004-11-09 18:39:53.000000', NULL, 1),
(1001545, 118335, 20779, '<td valign="top">Beautiful, crisp, deeply saturated - great use of negative space (which I am usually tired of in this type of use). 9.</td>', 'Beautiful, crisp, deeply saturated - great use of negative space (which I am usually tired of in this type of use). 9.', '2004-11-09 18:40:40.000000', NULL, 1),
(1001547, 119303, 20779, '<td valign="top">Some may not see this as screaming calendar, but I do and I''d buy it!!</td>', 'Some may not see this as screaming calendar, but I do and I''d buy it!!', '2004-11-09 18:41:15.000000', NULL, 1),
(1001549, 118370, 20779, '<td valign="top">Nothing to say, other than perfectly done. Not sure that such a personal portrait would appear in a calendar, but I am treating this as more of an "open" and it could certainly be something you wanted to look at all month if you had a calendar made up of your family, favorites, etc. 9.</td>', 'Nothing to say, other than perfectly done. Not sure that such a personal portrait would appear in a calendar, but I am treating this as more of an "open" and it could certainly be something you wanted to look at all month if you had a calendar made up of your family, favorites, etc. 9.', '2004-11-09 18:43:50.000000', NULL, 1),
(1001550, 119387, 20779, '<td valign="top">Perfect, classic lighting and composition with just enough of a freshness to really stand apart. Just fabulous.</td>', 'Perfect, classic lighting and composition with just enough of a freshness to really stand apart. Just fabulous.', '2004-11-09 18:44:41.000000', NULL, 1),
(1001551, 119554, 25742, '<td valign="top">The horizon is quite a bit tilted to the left. Nice sunrays in the far BG.<br/>Bit too dull for my tastes (colour vise) -  needs a litle more "sparkle"</td>', 'The horizon is quite a bit tilted to the left. Nice sunrays in the far BG.Bit too dull for my tastes (colour vise) -  needs a litle more "sparkle"', '2004-11-09 18:45:11.000000', NULL, 1),
(1001553, 118335, 25742, '<td valign="top">Why April?</td>', 'Why April?', '2004-11-09 18:46:00.000000', NULL, 1),
(1001554, 119332, 20779, '<td valign="top">This caught my eye immediately and kept me hooked. I absolutely love the perspective and sparkling clarity. Perfect crop chosen in my opinion (in or out of the camera). Terrific shot for a calendar!</td>', 'This caught my eye immediately and kept me hooked. I absolutely love the perspective and sparkling clarity. Perfect crop chosen in my opinion (in or out of the camera). Terrific shot for a calendar!', '2004-11-09 18:46:09.000000', NULL, 1),
(1001555, 119250, 25742, '<td valign="top">I like this calendar</td>', 'I like this calendar', '2004-11-09 18:46:42.000000', NULL, 1),
(1001556, 119453, 20779, '<td valign="top">I wouldn''t be surprised to see this ribbon. It isn''t just another dog/pet shot by a long shot! I just love the angle and perspective giving him his wonderfully soulful appearance. Perfection in a studio shot.</td>', 'I wouldn''t be surprised to see this ribbon. It isn''t just another dog/pet shot by a long shot! I just love the angle and perspective giving him his wonderfully soulful appearance. Perfection in a studio shot.', '2004-11-09 18:47:56.000000', NULL, 1),
(1001561, 119387, 25742, '<td valign="top">beautiful. nice reds on ground. the picture does not portray strom in my mind, maybe the day after. or the lull before the storm?</td>', 'beautiful. nice reds on ground. the picture does not portray strom in my mind, maybe the day after. or the lull before the storm?', '2004-11-09 18:48:42.000000', NULL, 1),
(1001562, 118740, 20779, '<td valign="top">I could swear I have seen this???? Love it either way. Almost as if seeing it thorugh glass. One of my favorites.</td>', 'I could swear I have seen this???? Love it either way. Almost as if seeing it thorugh glass. One of my favorites.', '2004-11-09 18:49:02.000000', NULL, 1),
(1001566, 119286, 20779, '<td valign="top">This has a wonderful grace and balance. Terrific lighting and color. I think your choice of border is just perfect.</td>', 'This has a wonderful grace and balance. Terrific lighting and color. I think your choice of border is just perfect.', '2004-11-09 18:50:11.000000', NULL, 1),
(1001568, 118954, 25742, '<td valign="top">almost surreal difference between colourful ground and lacklustre sky/trees. don''t know about the white border though. maybe rather black? or gray? twotone? Red?</td>', 'almost surreal difference between colourful ground and lacklustre sky/trees. don''t know about the white border though. maybe rather black? or gray? twotone? Red?', '2004-11-09 18:50:39.000000', NULL, 1),
(1001570, 119285, 20779, '<td valign="top">This took my breath away when I first viewed it. Love coming back to it.</td>', 'This took my breath away when I first viewed it. Love coming back to it.', '2004-11-09 18:50:49.000000', NULL, 1),
(1001573, 118682, 25742, '<td valign="top">use full size man! :)<br/>when you''re competing against bigger images you loose with a smaller one, no matter how nice it is</td>', 'use full size man! :)when you''re competing against bigger images you loose with a smaller one, no matter how nice it is', '2004-11-09 18:51:51.000000', NULL, 1),
(1001574, 118954, 20779, '<td valign="top">This "feels" like November as I know it. In a perfect world, I would have preferred a less wide path, but that wasn''t up to you! One of my favorites for Calendar.</td>', 'This "feels" like November as I know it. In a perfect world, I would have preferred a less wide path, but that wasn''t up to you! One of my favorites for Calendar.', '2004-11-09 18:52:11.000000', NULL, 1),
(1001575, 118778, 25742, '<td valign="top">very nice urban calendar<br/>Arcitectual digest complementary calendar?</td>', 'very nice urban calendarArcitectual digest complementary calendar?', '2004-11-09 18:52:46.000000', NULL, 1),
(1001576, 118370, 24642, '<td valign="top">My highest rated shot for this challenge. Very classic and I  think that it has the spirit of may.  Can''t  really find a single flaw.</td>', 'My highest rated shot for this challenge. Very classic and I  think that it has the spirit of may.  Can''t  really find a single flaw.', '2004-11-09 18:53:06.000000', NULL, 1),
(1001578, 118605, 25742, '<td valign="top">the building on the left leans a bit too much into the photo, esp near the left border</td>', 'the building on the left leans a bit too much into the photo, esp near the left border', '2004-11-09 18:53:58.000000', NULL, 1),
(1001580, 118895, 25742, '<td valign="top">sponsored by swiss-miss?</td>', 'sponsored by swiss-miss?', '2004-11-09 18:54:38.000000', NULL, 1),
(1001581, 118607, 24642, '<td valign="top">Good viewpoint, I like the wet part of the beach and the birds really add life to the shot.</td>', 'Good viewpoint, I like the wet part of the beach and the birds really add life to the shot.', '2004-11-09 18:55:07.000000', NULL, 1),
(1001582, 119582, 20779, '<td valign="top">This image keeps bringing me back; she almost appears painted in or something. I think it is a great shot and intriguing in its overall mood andlight. I can see this as a calendar piece.</td>', 'This image keeps bringing me back; she almost appears painted in or something. I think it is a great shot and intriguing in its overall mood andlight. I can see this as a calendar piece.', '2004-11-09 18:55:43.000000', NULL, 1),
(1001584, 119221, 20779, '<td valign="top">April diamonds? Unique and stunning piece.</td>', 'April diamonds? Unique and stunning piece.', '2004-11-09 18:56:23.000000', NULL, 1),
(1001586, 119377, 25742, '<td valign="top">this is in my opionon very likely a top 10, but don''t get your hopes up, since I''m almost always wrong about that ;)<br/>I like it a lot anyhow.</td>', 'this is in my opionon very likely a top 10, but don''t get your hopes up, since I''m almost always wrong about that ;)I like it a lot anyhow.', '2004-11-09 18:56:36.000000', NULL, 1),
(1001587, 118627, 20779, '<td valign="top">Clever, and extremely well composed and lit.</td>', 'Clever, and extremely well composed and lit.', '2004-11-09 18:56:58.000000', NULL, 1),
(1001592, 119569, 25742, '<td valign="top">horizon horribly tilted. Nice Aurora though. Which month?</td>', 'horizon horribly tilted. Nice Aurora though. Which month?', '2004-11-09 18:58:06.000000', NULL, 1),
(1001593, 118991, 20779, '<td valign="top">Gorgeous shot and could be part of a calendar selection easily. There is a bit of fog or softness that dulls it somewhat and it appears the slightest bit tilted, but could be an illusion.</td>', 'Gorgeous shot and could be part of a calendar selection easily. There is a bit of fog or softness that dulls it somewhat and it appears the slightest bit tilted, but could be an illusion.', '2004-11-09 18:58:45.000000', NULL, 1),
(1001594, 118954, 24642, '<td valign="top">Good composition that fits well in the square format.  The burning in the sky above the trees seems a bit to obvious, but I have to admit that it adds mood to the shot.</td>', 'Good composition that fits well in the square format.  The burning in the sky above the trees seems a bit to obvious, but I have to admit that it adds mood to the shot.', '2004-11-09 18:58:55.000000', NULL, 1),
(1001598, 118043, 20779, '<td valign="top">This would have been perfect for Bizarre Nature!! The gazebo looks familiar, too. I love this shot and expect it to do quite well!</td>', 'This would have been perfect for Bizarre Nature!! The gazebo looks familiar, too. I love this shot and expect it to do quite well!', '2004-11-09 18:59:47.000000', NULL, 1),
(1001599, 119286, 25742, '<td valign="top">whoops. risky border there :)<br/>I like that kind of border myself, how do you do it?<br/>The landscape has a kind of painted feeling to it, almost not real.</td>', 'whoops. risky border there :)I like that kind of border myself, how do you do it?The landscape has a kind of painted feeling to it, almost not real.', '2004-11-09 19:00:00.000000', NULL, 1),
(1001600, 119434, 20779, '<td valign="top">A perfect classic. Can''t touch it.</td>', 'A perfect classic. Can''t touch it.', '2004-11-09 19:00:12.000000', NULL, 1),
(1001602, 118987, 20779, '<td valign="top">Simply stunning. I really like the slightly elongated crop. Gives it a real "flow" and grace.</td>', 'Simply stunning. I really like the slightly elongated crop. Gives it a real "flow" and grace.', '2004-11-09 19:00:55.000000', NULL, 1),
(1001603, 118335, 24642, '<td valign="top">I like the big blue sky and the balance between the elements.</td>', 'I like the big blue sky and the balance between the elements.', '2004-11-09 19:01:03.000000', NULL, 1),
(1001604, 119332, 19608, '<td valign="top">Whoa.  The angle of this is very unusual to say the least.  It adds a lot of tension - like what the heck?  Focus (and soft focused background) is superb.  Exposure is right on - but if the hot spots in the right bottom could have been shaded, it would be stronger.  Great color saturation.</td>', 'Whoa.  The angle of this is very unusual to say the least.  It adds a lot of tension - like what the heck?  Focus (and soft focused background) is superb.  Exposure is right on - but if the hot spots in the right bottom could have been shaded, it would be stronger.  Great color saturation.', '2004-11-09 19:01:16.000000', NULL, 1),
(1001605, 118778, 20779, '<td valign="top">Just adore the golden and aqua reflections mirrored. I would buy the calnedar full of these!</td>', 'Just adore the golden and aqua reflections mirrored. I would buy the calnedar full of these!', '2004-11-09 19:01:45.000000', NULL, 1),
(1001607, 119491, 20779, '<td valign="top">Beautiful softness captured. I could be happy viewing this serenely all month!</td>', 'Beautiful softness captured. I could be happy viewing this serenely all month!', '2004-11-09 19:02:33.000000', NULL, 1),
(1001608, 119155, 25742, '<td valign="top">pyromaniacs association''s calendar?</td>', 'pyromaniacs association''s calendar?', '2004-11-09 19:02:53.000000', NULL, 1),
(1001609, 118312, 25742, '<td valign="top">hope he''s not hungry</td>', 'hope he''s not hungry', '2004-11-09 19:03:10.000000', NULL, 1),
(1001615, 119332, 25742, '<td valign="top">nice posture. unfortunately the green and blue on the head/nape blends a bit too much into the BG so the bird does not stand out as much as I''d like. very nice though.</td>', 'nice posture. unfortunately the green and blue on the head/nape blends a bit too much into the BG so the bird does not stand out as much as I''d like. very nice though.', '2004-11-09 19:04:35.000000', NULL, 1),
(1001617, 119285, 24642, '<td valign="top">A shot I would pick for a calendar.  Good classic composition,  creative DOF and superb colour balance.  One of the highest rated in the challenge.</td>', 'A shot I would pick for a calendar.  Good classic composition,  creative DOF and superb colour balance.  One of the highest rated in the challenge.', '2004-11-09 19:05:31.000000', NULL, 1),
(1001620, 117888, 24976, '<td valign="top">this is really beautiful, the reflection and the colors are great and the surface of the water is wonderfully captured... feels like im floating on the water right now. great stuff</td>', 'this is really beautiful, the reflection and the colors are great and the surface of the water is wonderfully captured... feels like im floating on the water right now. great stuff', '2004-11-09 19:07:42.000000', NULL, 1),
(1001621, 119155, 24642, '<td valign="top">Not the typical calendar photo.  Very powerful and different.</td>', 'Not the typical calendar photo.  Very powerful and different.', '2004-11-09 19:07:50.000000', NULL, 1),
(1001622, 119303, 25742, '<td valign="top">a little bit too depressing for a calendar for me, but a nice photo</td>', 'a little bit too depressing for a calendar for me, but a nice photo', '2004-11-09 19:07:50.000000', NULL, 1),
(1001630, 119526, 20779, '<td valign="top">Spectacular classic. Well done and perfect calendar material!</td>', 'Spectacular classic. Well done and perfect calendar material!', '2004-11-09 19:10:04.000000', NULL, 1),
(1001632, 119302, 20779, '<td valign="top">Just love this type of shot. Well done and great for calendar. Would prefer just a little less "centered", but that''s a nit-pik.</td>', 'Just love this type of shot. Well done and great for calendar. Would prefer just a little less "centered", but that''s a nit-pik.', '2004-11-09 19:11:03.000000', NULL, 1),
(1001633, 119356, 24976, '<td valign="top">something about the composition is throwing me off.... I feel like it should either be closer up almost sihluette like or a bit farther back. and I would have liked something to balance the yellow on the right.</td>', 'something about the composition is throwing me off.... I feel like it should either be closer up almost sihluette like or a bit farther back. and I would have liked something to balance the yellow on the right.', '2004-11-09 19:11:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1001634, 119519, 20779, '<td valign="top">Very striking shot.</td>', 'Very striking shot.', '2004-11-09 19:11:24.000000', NULL, 1),
(1001638, 119220, 24642, '<td valign="top">A shot I would pick for a calendar.  Good composition,  simple and peaceful.  I like the title, shows creative thinking and somehow fits the photograph better than a full month name.<br/> <br/>Very good work.</td>', 'A shot I would pick for a calendar.  Good composition,  simple and peaceful.  I like the title, shows creative thinking and somehow fits the photograph better than a full month name. Very good work.', '2004-11-09 19:12:49.000000', NULL, 1),
(1001639, 118672, 20779, '<td valign="top">Gorgeous amber highlighting the horizon and gret perspective. Very soothing shot for a calendar.</td>', 'Gorgeous amber highlighting the horizon and gret perspective. Very soothing shot for a calendar.', '2004-11-09 19:13:12.000000', NULL, 1),
(1001641, 119572, 24976, '<td valign="top">Im missing summer so much already and winter hasnt even started yet :-(... so depressing.... But your picture is very beautiful! The only suggestion i would make is that the clouds could be a touch whiter.</td>', 'Im missing summer so much already and winter hasnt even started yet :-(... so depressing.... But your picture is very beautiful! The only suggestion i would make is that the clouds could be a touch whiter.', '2004-11-09 19:13:17.000000', NULL, 1),
(1001644, 119079, 24976, '<td valign="top">nice and simple 8</td>', 'nice and simple 8', '2004-11-09 19:14:21.000000', NULL, 1),
