INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1004093, 118043, 17033, '<td valign="top">Great feeling of movement...I wonder if you''d taken the shot from lower down whether you could have really framed the bandstand and the two other trees?</td>', 'Great feeling of movement...I wonder if you''d taken the shot from lower down whether you could have really framed the bandstand and the two other trees?', '2004-11-10 14:20:26.000000', NULL, 1),
(1004098, 118623, 17033, '<td valign="top">Less grass, more sky would have been better IMO.</td>', 'Less grass, more sky would have been better IMO.', '2004-11-10 14:22:06.000000', NULL, 1),
(1004111, 119524, 17033, '<td valign="top">I like the extreme lighting...the ferns look great.</td>', 'I like the extreme lighting...the ferns look great.', '2004-11-10 14:24:34.000000', NULL, 1),
(1004121, 119155, 17033, '<td valign="top">Love this, love the patterns in the flames, love the pallette shapes. I can hear your lens cracking in the heat! Blistering shot!</td>', 'Love this, love the patterns in the flames, love the pallette shapes. I can hear your lens cracking in the heat! Blistering shot!', '2004-11-10 14:26:39.000000', NULL, 1),
(1004126, 119190, 17033, '<td valign="top">Magnificent capture and processing</td>', 'Magnificent capture and processing', '2004-11-10 14:27:38.000000', NULL, 1),
(1004135, 118335, 17033, '<td valign="top">Starkly, succulently superlative. Special!</td>', 'Starkly, succulently superlative. Special!', '2004-11-10 14:31:27.000000', NULL, 1),
(1004138, 119336, 17033, '<td valign="top">Magical capture. Well done!</td>', 'Magical capture. Well done!', '2004-11-10 14:32:57.000000', NULL, 1),
(1004147, 118895, 17033, '<td valign="top">Closer crop would be better IMO. Good though.</td>', 'Closer crop would be better IMO. Good though.', '2004-11-10 14:34:59.000000', NULL, 1),
(1004198, 119576, 25143, '<td valign="top">overall an excellent composition</td>', 'overall an excellent composition', '2004-11-10 14:51:10.000000', NULL, 1),
(1004248, 118946, 25371, '<td valign="top">I like the blue colour of the sky and the water. Well done.</td>', 'I like the blue colour of the sky and the water. Well done.', '2004-11-10 15:09:03.000000', NULL, 1),
(1004331, 119434, 16148, '<td valign="top">Beautiful details that work well in black and white.  Great lighting and use of negative space.  My pick for the challenge.  Good luck!</td>', 'Beautiful details that work well in black and white.  Great lighting and use of negative space.  My pick for the challenge.  Good luck!', '2004-11-10 15:35:01.000000', NULL, 1),
(1004355, 119060, 25371, '<td valign="top">Wow. I''m impressed. Very well done.</td>', 'Wow. I''m impressed. Very well done.', '2004-11-10 15:44:59.000000', NULL, 1),
(1004379, 119434, 25371, '<td valign="top">Definitely one of the best in this contest... Congratulation.</td>', 'Definitely one of the best in this contest... Congratulation.', '2004-11-10 15:51:16.000000', NULL, 1),
(1004401, 119220, 8860, '<td valign="top">Very cool, simple shot. Like it muchly.</td>', 'Very cool, simple shot. Like it muchly.', '2004-11-10 15:58:47.000000', NULL, 1),
(1004497, 119190, 8860, '<td valign="top">I''m sure this has been heavily edited - but it''s very well done (for a change). Those pools of light are dramatic and nicely picked up. I think you''ve dodged too far in the clouds though and a touch more pick-up on the foreground would be good.</td>', 'I''m sure this has been heavily edited - but it''s very well done (for a change). Those pools of light are dramatic and nicely picked up. I think you''ve dodged too far in the clouds though and a touch more pick-up on the foreground would be good.', '2004-11-10 16:31:06.000000', NULL, 1),
(1004627, 119585, 22010, '<td valign="top">I''m not sure I''m a big fan of the colors here. But I am a big fan of this composition and the lighting. It''s more real somehow. Nice picture.</td>', 'I''m not sure I''m a big fan of the colors here. But I am a big fan of this composition and the lighting. It''s more real somehow. Nice picture.', '2004-11-10 17:10:45.000000', NULL, 1),
(1004635, 118963, 22010, '<td valign="top">Is that Schilling? I''m from MA and not a big fan of Bush. On to the picture. The focus is on the seal, which is okay. But as the subject is W himself, I wish you had tried him instead. Composition is good, the crowd behind doesn''t detract from the picture whatsoever. Nice shot.</td>', 'Is that Schilling? I''m from MA and not a big fan of Bush. On to the picture. The focus is on the seal, which is okay. But as the subject is W himself, I wish you had tried him instead. Composition is good, the crowd behind doesn''t detract from the picture whatsoever. Nice shot.', '2004-11-10 17:13:00.000000', NULL, 1),
(1004642, 118974, 22010, '<td valign="top">The desat here works well. A wish the leaves were a brighter red though. I''m sure you tried adjusting the levels. Nice composition.</td>', 'The desat here works well. A wish the leaves were a brighter red though. I''m sure you tried adjusting the levels. Nice composition.', '2004-11-10 17:14:31.000000', NULL, 1),
(1004712, 119347, 21069, '<td valign="top">perfect waterfall pic - couldn''t ask for anything more - just magical</td>', 'perfect waterfall pic - couldn''t ask for anything more - just magical', '2004-11-10 17:50:17.000000', NULL, 1),
(1004735, 117726, 11793, '<td valign="top">seems just about everything in this is out of focus?<br/></td>', 'seems just about everything in this is out of focus?', '2004-11-10 18:00:33.000000', NULL, 1),
(1004739, 119190, 11793, '<td valign="top">well that sums up the sky around here in november - if the sun happenes to peak out...<br/> <br/>striking photo - fair amount of noise in the sky i am not to fond of.</td>', 'well that sums up the sky around here in november - if the sun happenes to peak out... striking photo - fair amount of noise in the sky i am not to fond of.', '2004-11-10 18:01:59.000000', NULL, 1),
(1004741, 118043, 11793, '<td valign="top">well done - this made me lean with the wind for a second...<br/>good luck</td>', 'well done - this made me lean with the wind for a second...good luck', '2004-11-10 18:02:42.000000', NULL, 1),
(1004870, 119220, 7543, '<td valign="top">Great work, highest rating I gave this time. Love the texture and the matte-reflecting of the water. Form of the branches great as well. Super work.</td>', 'Great work, highest rating I gave this time. Love the texture and the matte-reflecting of the water. Form of the branches great as well. Super work.', '2004-11-10 18:49:14.000000', NULL, 1),
(1004908, 119221, 5677, '<td valign="top">This is a wonderful photo.  Is that Albany, NY?  I recognize the egg.  I''ve never seen Albany look so beautiful.</td>', 'This is a wonderful photo.  Is that Albany, NY?  I recognize the egg.  I''ve never seen Albany look so beautiful.', '2004-11-10 19:04:42.000000', NULL, 1),
(1004930, 119399, 8860, '<td valign="top">Well you know - there are landscapes, and then there are LANDSCAPES! And this is a beauty. I often find it tough to vote on shots of wonderful scenes unless I can see some creative input in the shot itself. <br/> <br/>Here, I see excellenece in every respect - the POV, time of day, DOF, choice of lens, exposure and processing. I love it and it deserves to grace a well printed calendar. You will surely ribbon with this one.</td>', 'Well you know - there are landscapes, and then there are LANDSCAPES! And this is a beauty. I often find it tough to vote on shots of wonderful scenes unless I can see some creative input in the shot itself.  Here, I see excellenece in every respect - the POV, time of day, DOF, choice of lens, exposure and processing. I love it and it deserves to grace a well printed calendar. You will surely ribbon with this one.', '2004-11-10 19:17:16.000000', NULL, 1),
(1004931, 118944, 1202, '<td valign="top">I think too much sky for a calendar shot. Needs more in the foreground for me.  6</td>', 'I think too much sky for a calendar shot. Needs more in the foreground for me.  6', '2004-11-10 19:17:35.000000', NULL, 1),
(1004933, 119582, 1202, '<td valign="top">Nice shot. What made you pick March?  7</td>', 'Nice shot. What made you pick March?  7', '2004-11-10 19:19:01.000000', NULL, 1),
(1004940, 119579, 1202, '<td valign="top">Good photo.  I prefer the stem to start on the left and pull ones eye into the bloom.  Also would like to see more detail in the center of blossom.  6</td>', 'Good photo.  I prefer the stem to start on the left and pull ones eye into the bloom.  Also would like to see more detail in the center of blossom.  6', '2004-11-10 19:21:07.000000', NULL, 1),
(1004944, 119437, 1202, '<td valign="top">Great job. It looks like the lights actually light the sheep, is that so?  9</td>', 'Great job. It looks like the lights actually light the sheep, is that so?  9', '2004-11-10 19:22:43.000000', NULL, 1),
(1004952, 119295, 1202, '<td valign="top">With the goulish effect you have for October it makes me wonder what the other 11 would look like.  Not typical calendar to me. 4</td>', 'With the goulish effect you have for October it makes me wonder what the other 11 would look like.  Not typical calendar to me. 4', '2004-11-10 19:25:06.000000', NULL, 1),
(1005173, 118335, 20889, '<td valign="top">Outstanding</td>', 'Outstanding', '2004-11-10 21:31:02.000000', NULL, 1),
(1005176, 118288, 20889, '<td valign="top">Stands to be a bit busy, but for a calendar looks good 9</td>', 'Stands to be a bit busy, but for a calendar looks good 9', '2004-11-10 21:33:30.000000', NULL, 1),
(1005263, 119579, 22010, '<td valign="top">Seems a bit out of focus to me. I think the petals draw my attention and the focus is on the a leaf. I really like the colors though, and the composition is great.</td>', 'Seems a bit out of focus to me. I think the petals draw my attention and the focus is on the a leaf. I really like the colors though, and the composition is great.', '2004-11-10 22:37:32.000000', NULL, 1),
(1005268, 119070, 22010, '<td valign="top">Very nice colors. The lawn and sky are amazing. The larger tree is slightly underwhelming though. EIther way, I really like this picture.</td>', 'Very nice colors. The lawn and sky are amazing. The larger tree is slightly underwhelming though. EIther way, I really like this picture.', '2004-11-10 22:39:09.000000', NULL, 1),
(1005272, 118740, 22010, '<td valign="top">I like the effect. It''s a bit overdone especially in the top right, but I like the way the boats turned out.</td>', 'I like the effect. It''s a bit overdone especially in the top right, but I like the way the boats turned out.', '2004-11-10 22:40:01.000000', NULL, 1),
(1005291, 118312, 7969, '<td valign="top">very nice lion, was it taken in a zoo?  I only ask cuz he doesn''t have many scars? maybe he is a young lion.</td>', 'very nice lion, was it taken in a zoo?  I only ask cuz he doesn''t have many scars? maybe he is a young lion.', '2004-11-10 22:54:21.000000', NULL, 1),
(1005310, 119018, 27496, '<td valign="top">I liked the overall photo but thought the sky was too washed out and my eyes get pulled to the white there instead of the green, red, and yellows below.</td>', 'I liked the overall photo but thought the sky was too washed out and my eyes get pulled to the white there instead of the green, red, and yellows below.', '2004-11-10 23:19:57.000000', NULL, 1),
(1005325, 119077, 19708, '<td valign="top">Perfect!<br/>This couldn''t have met the challenge better. Perfect composition, lighting and detail - with a border even! LOL<br/>Working for Hallmark®  are we? ((10))<br/></td>', 'Perfect!This couldn''t have met the challenge better. Perfect composition, lighting and detail - with a border even! LOLWorking for Hallmark®  are we? ((10))', '2004-11-10 23:32:24.000000', NULL, 1),
(1005326, 118939, 19708, '<td valign="top">Nicely posed and with a great smile.<br/>Great take on the challenge! ((9))</td>', 'Nicely posed and with a great smile.Great take on the challenge! ((9))', '2004-11-10 23:34:28.000000', NULL, 1),
(1005341, 118691, 3724, '<td valign="top">Neat composition.......</td>', 'Neat composition.......', '2004-11-10 23:46:52.000000', NULL, 1),
(1005353, 119077, 3724, '<td valign="top">nice eyes and expression on this dog.......</td>', 'nice eyes and expression on this dog.......', '2004-11-10 23:55:31.000000', NULL, 1),
(1005367, 118420, 23561, '<td valign="top">I really like the detail on  the edges of the flower and the shallow DOF on the stem, but I wish the lighting on the center was a bit brighter so I could see more detail in the center instead of shadow. I might have clipped off a little more of the blank space on top, but what do I know?:) A standout for sure. 9</td>', 'I really like the detail on  the edges of the flower and the shallow DOF on the stem, but I wish the lighting on the center was a bit brighter so I could see more detail in the center instead of shadow. I might have clipped off a little more of the blank space on top, but what do I know?:) A standout for sure. 9', '2004-11-11 00:06:46.000000', NULL, 1),
(1005370, 119491, 23561, '<td valign="top">Excellent. Beautiful capture of what probably is a just a plain old ugly bridge! 10.</td>', 'Excellent. Beautiful capture of what probably is a just a plain old ugly bridge! 10.', '2004-11-11 00:08:57.000000', NULL, 1),
(1005378, 119368, 23561, '<td valign="top">I like the idea for this, but the lighting or color seems to be off. I think what seems to me to be the different textures from the cards are doing something with the lighting and its making the colors seem off on most of the cards on the left and the focus feels a bit too soft also.</td>', 'I like the idea for this, but the lighting or color seems to be off. I think what seems to me to be the different textures from the cards are doing something with the lighting and its making the colors seem off on most of the cards on the left and the focus feels a bit too soft also.', '2004-11-11 00:17:33.000000', NULL, 1),
(1005434, 118740, 5044, '<td valign="top">Very, very nice. Just a little overexposed in the white reflections in the water, but otherwise perfect.</td>', 'Very, very nice. Just a little overexposed in the white reflections in the water, but otherwise perfect.', '2004-11-11 02:10:19.000000', NULL, 1),
(1005436, 118316, 5044, '<td valign="top">Not your typical November, I hope for you. Personally, I would have called this December.</td>', 'Not your typical November, I hope for you. Personally, I would have called this December.', '2004-11-11 02:12:19.000000', NULL, 1),
(1005437, 119078, 5044, '<td valign="top">A few more geese, and they almost could have spelled November. :)</td>', 'A few more geese, and they almost could have spelled November. :)', '2004-11-11 02:13:40.000000', NULL, 1),
(1005440, 119569, 5044, '<td valign="top">Last I heard, Aurora was not a month. The colour of the aurora is nice, but the whole photo is green, which is not so nice. Also the horizon is badly titled to the left.</td>', 'Last I heard, Aurora was not a month. The colour of the aurora is nice, but the whole photo is green, which is not so nice. Also the horizon is badly titled to the left.', '2004-11-11 02:16:18.000000', NULL, 1),
(1005443, 119219, 5044, '<td valign="top">Funny! But I really don''t like the desaturation done on this photo.</td>', 'Funny! But I really don''t like the desaturation done on this photo.', '2004-11-11 02:18:05.000000', NULL, 1),
(1005446, 118043, 5044, '<td valign="top">Timber! Nice, very nice. Good work Ben! Or somebody who lives near Ben.</td>', 'Timber! Nice, very nice. Good work Ben! Or somebody who lives near Ben.', '2004-11-11 02:19:31.000000', NULL, 1),
(1005453, 118939, 23251, '<td valign="top">Refreshingly different take on the challenge, well photographed and a beautiful model.  Very slight shadow cast at the back.</td>', 'Refreshingly different take on the challenge, well photographed and a beautiful model.  Very slight shadow cast at the back.', '2004-11-11 02:23:00.000000', NULL, 1),
(1005470, 118387, 23251, '<td valign="top">I don''t normally mind borders but this one is too over done and spoils what looks like a great photo.</td>', 'I don''t normally mind borders but this one is too over done and spoils what looks like a great photo.', '2004-11-11 02:37:50.000000', NULL, 1),
(1005511, 119285, 28963, '<td valign="top">Nice attempt, focus should have been better though, the foreground is not sharp enough imo and the background is too blury, it becomes distracting. I like the shapes though.</td>', 'Nice attempt, focus should have been better though, the foreground is not sharp enough imo and the background is too blury, it becomes distracting. I like the shapes though.', '2004-11-11 03:51:51.000000', NULL, 1),
(1005561, 119434, 27939, '<td valign="top">You got this one just right, well done</td>', 'You got this one just right, well done', '2004-11-11 04:49:46.000000', NULL, 1),
(1005584, 119581, 23251, '<td valign="top">Great idea I just don''t understand all the empty space at the bottom!</td>', 'Great idea I just don''t understand all the empty space at the bottom!', '2004-11-11 05:55:58.000000', NULL, 1),
(1005585, 119247, 23251, '<td valign="top">She made me smile tooo.  Great shot and a cute little girl.</td>', 'She made me smile tooo.  Great shot and a cute little girl.', '2004-11-11 05:57:32.000000', NULL, 1),
(1005592, 118316, 23251, '<td valign="top">A tighter crop on the right hand side would have helped IMHO.</td>', 'A tighter crop on the right hand side would have helped IMHO.', '2004-11-11 06:19:15.000000', NULL, 1),
(1005593, 118094, 23251, '<td valign="top">The DOF is just a tad to shallow, it would have been better IMHO to have all of the fungi in focus.</td>', 'The DOF is just a tad to shallow, it would have been better IMHO to have all of the fungi in focus.', '2004-11-11 06:26:24.000000', NULL, 1),
(1005625, 119399, 26487, '<td valign="top">WOW, nice! <br/></td>', 'WOW, nice! ', '2004-11-11 07:26:58.000000', NULL, 1),
(1005632, 119554, 26487, '<td valign="top">I like the light from the sky and the repetation of the poles. Let''s try to crop the below out and make the front pole as foreground. I am not a professional photographer, but let me know if it helps. And the horizon maybe a little tilted. Not sure if you intended or not. 7</td>', 'I like the light from the sky and the repetation of the poles. Let''s try to crop the below out and make the front pole as foreground. I am not a professional photographer, but let me know if it helps. And the horizon maybe a little tilted. Not sure if you intended or not. 7', '2004-11-11 07:34:57.000000', NULL, 1),
(1005634, 119336, 27161, '<td valign="top">10 - Nice DOF, beautiful dog.  He looks like he makes a great subject.  Good job.</td>', '10 - Nice DOF, beautiful dog.  He looks like he makes a great subject.  Good job.', '2004-11-11 07:35:56.000000', NULL, 1),
(1005637, 118944, 27161, '<td valign="top">10 - Beautiful sky.  I don''t think I''ve ever seen such a perfect dispersion of the same sized clouds.  Good job incorporating the light house.</td>', '10 - Beautiful sky.  I don''t think I''ve ever seen such a perfect dispersion of the same sized clouds.  Good job incorporating the light house.', '2004-11-11 07:37:04.000000', NULL, 1),
(1005640, 119453, 27161, '<td valign="top">10 - Nice shot.  Beautiful dog.  I need to get a dog.  I''m more of a Basset Hound fan though.</td>', '10 - Nice shot.  Beautiful dog.  I need to get a dog.  I''m more of a Basset Hound fan though.', '2004-11-11 07:38:25.000000', NULL, 1),
(1005643, 119377, 27161, '<td valign="top">10 - Beautiful colors and subject.  Good job.</td>', '10 - Beautiful colors and subject.  Good job.', '2004-11-11 07:40:00.000000', NULL, 1),
(1005644, 118672, 27161, '<td valign="top">9 - Gorgeous colors, but that stuff in the water (foreground) looks kind of icky.  I would have considered cropping it out.</td>', '9 - Gorgeous colors, but that stuff in the water (foreground) looks kind of icky.  I would have considered cropping it out.', '2004-11-11 07:41:44.000000', NULL, 1),
(1005646, 118605, 27161, '<td valign="top">9 - Gorgeous lighting. Would have preferred it without the blurry people, but its difficult to control the crowd I guess.</td>', '9 - Gorgeous lighting. Would have preferred it without the blurry people, but its difficult to control the crowd I guess.', '2004-11-11 07:43:06.000000', NULL, 1),
(1005648, 119584, 27161, '<td valign="top">9 - Great plant pic.  The plants in the background make the foreground plant a little hard to pull out in some places.  Perhaps taking the shot at an upward angle might have worked better.</td>', '9 - Great plant pic.  The plants in the background make the foreground plant a little hard to pull out in some places.  Perhaps taking the shot at an upward angle might have worked better.', '2004-11-11 07:45:17.000000', NULL, 1),
(1005649, 118857, 27161, '<td valign="top">9 - The only thing I can think of that would improve this would be a little more lighting on the plum.  It looks like it was taken on a dark day.  Good job.</td>', '9 - The only thing I can think of that would improve this would be a little more lighting on the plum.  It looks like it was taken on a dark day.  Good job.', '2004-11-11 07:47:10.000000', NULL, 1),
(1005650, 119220, 27161, '<td valign="top">9 - Perfect picture.  If I allowed myself to pic one more 10 this would be it.</td>', '9 - Perfect picture.  If I allowed myself to pic one more 10 this would be it.', '2004-11-11 07:48:33.000000', NULL, 1),
(1005651, 119190, 27161, '<td valign="top">9 - Perfect pic.  If I allowed myself to pic more than 4 10''s this would be one.</td>', '9 - Perfect pic.  If I allowed myself to pic more than 4 10''s this would be one.', '2004-11-11 07:49:21.000000', NULL, 1),
(1005653, 117888, 27161, '<td valign="top">9 - Gorgeous pic.  The sun is a little harsh.</td>', '9 - Gorgeous pic.  The sun is a little harsh.', '2004-11-11 07:50:39.000000', NULL, 1),
(1005655, 119061, 27161, '<td valign="top">8 - Great photo.  The sky line looks extremely blurry, and kind of an odd color.</td>', '8 - Great photo.  The sky line looks extremely blurry, and kind of an odd color.', '2004-11-11 07:52:43.000000', NULL, 1),
(1005656, 119078, 27161, '<td valign="top">8 - I''ve never seen such a large formation before.  The sun makes it a little harsh.</td>', '8 - I''ve never seen such a large formation before.  The sun makes it a little harsh.', '2004-11-11 07:54:05.000000', NULL, 1),
(1005658, 119394, 27161, '<td valign="top">8 - Nice bayou pic.  Good job.</td>', '8 - Nice bayou pic.  Good job.', '2004-11-11 07:55:29.000000', NULL, 1),
(1005722, 119286, 27562, '<td valign="top">Great shot.  However I do think it would be better without or with a different (solid) border.</td>', 'Great shot.  However I do think it would be better without or with a different (solid) border.', '2004-11-11 08:42:12.000000', NULL, 1),
(1005730, 118909, 27562, '<td valign="top">Good shot.  The clouds really add drama to the scene.  Too bad the black rigging had to be in the lower right hand of the frame.  It draws your eye away from the central focus of the image.</td>', 'Good shot.  The clouds really add drama to the scene.  Too bad the black rigging had to be in the lower right hand of the frame.  It draws your eye away from the central focus of the image.', '2004-11-11 08:53:48.000000', NULL, 1),
