(1007024, 119395, 18799, '<td valign="top">Very busy.  5</td>', 'Very busy.  5', '2004-11-12 00:48:23.000000', NULL, 1),
(1007031, 118559, 18799, '<td valign="top">This is a really nice shot.  What would have made it a great shot, and in my opinion, a ribbon contender, would be if you had applied the rule of thirds to the horizon line.  In other words, cut the sky down so the horizon line was 2/3 up the photo.   Still, a 7 from me</td>', 'This is a really nice shot.  What would have made it a great shot, and in my opinion, a ribbon contender, would be if you had applied the rule of thirds to the horizon line.  In other words, cut the sky down so the horizon line was 2/3 up the photo.   Still, a 7 from me', '2004-11-12 00:50:49.000000', NULL, 1),
(1007032, 118605, 18799, '<td valign="top">The motion of the people in the forground are distracting to me.   5</td>', 'The motion of the people in the forground are distracting to me.   5', '2004-11-12 00:51:30.000000', NULL, 1),
(1007034, 118627, 18799, '<td valign="top">A very nice photo, and I realize this is a subjective challenge, but what is the connection to June?  6</td>', 'A very nice photo, and I realize this is a subjective challenge, but what is the connection to June?  6', '2004-11-12 00:52:22.000000', NULL, 1),
(1007036, 119078, 18799, '<td valign="top">What a flock!  They are not a very strong element in this compostion and the brightness of the lower right is pretty overpowering so I probably wouldn''t want it on a calendar.  Never the less, I enjoyed looking at it.  6</td>', 'What a flock!  They are not a very strong element in this compostion and the brightness of the lower right is pretty overpowering so I probably wouldn''t want it on a calendar.  Never the less, I enjoyed looking at it.  6', '2004-11-12 00:54:36.000000', NULL, 1),
(1007038, 118949, 18799, '<td valign="top">I think the crop is a little awkward.  It leaves me wanting to see more of the tower, and the branches in front are hiding what there is of it.   5</td>', 'I think the crop is a little awkward.  It leaves me wanting to see more of the tower, and the branches in front are hiding what there is of it.   5', '2004-11-12 00:55:48.000000', NULL, 1),
(1007039, 118909, 18799, '<td valign="top">Works for me.  8</td>', 'Works for me.  8', '2004-11-12 00:56:20.000000', NULL, 1),
