(1007041, 119520, 18799, '<td valign="top">A little too much in the center for me.  5</td>', 'A little too much in the center for me.  5', '2004-11-12 00:58:30.000000', NULL, 1),
(1007044, 119347, 18799, '<td valign="top">Beautiful place.  I like the natural look of the water, as opposed to the silk look that is so popular these days.   9</td>', 'Beautiful place.  I like the natural look of the water, as opposed to the silk look that is so popular these days.   9', '2004-11-12 00:59:59.000000', NULL, 1),
