(1009957, 118370, 22479, '<td valign="top">Wonderful shot on all accounts. One of the stand outs of the bunch.</td>', 'Wonderful shot on all accounts. One of the stand outs of the bunch.', '2004-11-13 22:25:25.000000', NULL, 1),
(1009961, 118980, 22479, '<td valign="top">Nice framing.</td>', 'Nice framing.', '2004-11-13 22:26:43.000000', NULL, 1),
(1009970, 118954, 22479, '<td valign="top">Nice scene, fits the mood of November nicely with the contrast between the greens, browns, greys.</td>', 'Nice scene, fits the mood of November nicely with the contrast between the greens, browns, greys.', '2004-11-13 22:31:02.000000', NULL, 1),
(1009971, 119387, 22479, '<td valign="top">There is a lot to like about this photo. It looks a little overprocessed with the unnatural halos around the areas that had not been burned.</td>', 'There is a lot to like about this photo. It looks a little overprocessed with the unnatural halos around the areas that had not been burned.', '2004-11-13 22:31:11.000000', NULL, 1),
(1009972, 119179, 22479, '<td valign="top">Border is too prominent. Nice contrast of colors on the leaves and trees.</td>', 'Border is too prominent. Nice contrast of colors on the leaves and trees.', '2004-11-13 22:31:54.000000', NULL, 1),
(1009974, 118987, 22479, '<td valign="top">Nice colors on the foliage. Too much motion in the water, perhaps a faster shutter would have worked better.</td>', 'Nice colors on the foliage. Too much motion in the water, perhaps a faster shutter would have worked better.', '2004-11-13 22:33:28.000000', NULL, 1),
(1009976, 118672, 22479, '<td valign="top">Great colors. I think this fits the month of November.</td>', 'Great colors. I think this fits the month of November.', '2004-11-13 22:35:38.000000', NULL, 1),
(1009979, 118720, 22479, '<td valign="top">I like the way you framed this shot. The foreground is too dark and the sky is overexposed a little bit. Minor issues, excellent overall.</td>', 'I like the way you framed this shot. The foreground is too dark and the sky is overexposed a little bit. Minor issues, excellent overall.', '2004-11-13 22:37:54.000000', NULL, 1),
(1009982, 119434, 22479, '<td valign="top">Good exposure, the black background contrasts nicely.</td>', 'Good exposure, the black background contrasts nicely.', '2004-11-13 22:38:33.000000', NULL, 1),
(1009989, 118958, 22479, '<td valign="top">Nice framing, great sky.</td>', 'Nice framing, great sky.', '2004-11-13 22:41:36.000000', NULL, 1),
(1009991, 119491, 22479, '<td valign="top">Personally I like everything except the bridge. Sky, water, silhouette, wonderful. Border is a little bit too prominent.</td>', 'Personally I like everything except the bridge. Sky, water, silhouette, wonderful. Border is a little bit too prominent.', '2004-11-13 22:42:51.000000', NULL, 1),
(1009999, 118623, 22479, '<td valign="top">Outstanding colors. Framed well.</td>', 'Outstanding colors. Framed well.', '2004-11-13 22:44:52.000000', NULL, 1),
(1010003, 118043, 22479, '<td valign="top">Nice subject. Very dramatic.</td>', 'Nice subject. Very dramatic.', '2004-11-13 22:46:36.000000', NULL, 1),
(1010004, 119155, 22479, '<td valign="top">What a powerful image. Scary stuff. 8</td>', 'What a powerful image. Scary stuff. 8', '2004-11-13 22:47:22.000000', NULL, 1),
(1010006, 119577, 22479, '<td valign="top">Breathtaking vista. Only quibble is that the horizon could have been leveled. Very nice. 8</td>', 'Breathtaking vista. Only quibble is that the horizon could have been leveled. Very nice. 8', '2004-11-13 22:48:19.000000', NULL, 1),
(1010008, 119519, 22479, '<td valign="top">This is a wonderfully composed shot. Oversaturated on the cliff, and sky is overburned.</td>', 'This is a wonderfully composed shot. Oversaturated on the cliff, and sky is overburned.', '2004-11-13 22:51:05.000000', NULL, 1),
(1010011, 118312, 3306, '<td valign="top">A terrific close up. My favorite of the challenge. Good choice for March.</td>', 'A terrific close up. My favorite of the challenge. Good choice for March.', '2004-11-13 22:53:35.000000', NULL, 1),
(1010013, 119434, 3306, '<td valign="top">Absolutely beautiful. The lighting, focus and DOF are perfect. Great choice in using B &amp; W.</td>', 'Absolutely beautiful. The lighting, focus and DOF are perfect. Great choice in using B & W.', '2004-11-13 22:54:57.000000', NULL, 1),
(1010017, 119220, 3306, '<td valign="top">Very well done. One of my favorites of the challenge. This would look great on the wall.</td>', 'Very well done. One of my favorites of the challenge. This would look great on the wall.', '2004-11-13 22:56:11.000000', NULL, 1),
(1010041, 118857, 19437, '<td valign="top">Usually calendars don''t have such blurry backgrounds</td>', 'Usually calendars don''t have such blurry backgrounds', '2004-11-13 23:32:00.000000', NULL, 1),
(1010043, 118312, 19437, '<td valign="top">I would like to see more of the lion.</td>', 'I would like to see more of the lion.', '2004-11-13 23:32:43.000000', NULL, 1),
(1010044, 119288, 19437, '<td valign="top">Not enough of the horse for a calendar.<br/></td>', 'Not enough of the horse for a calendar.', '2004-11-13 23:33:36.000000', NULL, 1),
(1010047, 119481, 19437, '<td valign="top">DOF is much too shallow for calendars.</td>', 'DOF is much too shallow for calendars.', '2004-11-13 23:35:29.000000', NULL, 1),
(1010049, 119572, 19437, '<td valign="top">Would be much better with more of the beach cropped and not so much sky.</td>', 'Would be much better with more of the beach cropped and not so much sky.', '2004-11-13 23:36:21.000000', NULL, 1),
(1010053, 119570, 19437, '<td valign="top">Would be much better with more dof.</td>', 'Would be much better with more dof.', '2004-11-13 23:38:15.000000', NULL, 1),
(1010054, 119029, 19437, '<td valign="top">Not enough dof for a calendar.</td>', 'Not enough dof for a calendar.', '2004-11-13 23:38:53.000000', NULL, 1),
(1010055, 118778, 24546, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2004-11-13 23:39:11.000000', NULL, 1),
(1010057, 118380, 19437, '<td valign="top">The colors seem to be slightly harsh.</td>', 'The colors seem to be slightly harsh.', '2004-11-13 23:41:12.000000', NULL, 1),
